fn broadcast_arrays(a: Vec<i8>, b: Vec<i8>) -> (Vec<i8>, Vec<i8>) {
    let m = a.len();
    let n = b.len();
    // According to the problem statement, both `a` and `b` are non-empty
    // and one of these must hold: m == n, m == 1, or n == 1.
    assert!(m > 0 && n > 0, "Input arrays must be non-empty");
    assert!(m == n || m == 1 || n == 1, "Input shapes are not compatible");
    let out_len = m.max(n);

    let mut a_out = Vec::with_capacity(out_len);
    let mut b_out = Vec::with_capacity(out_len);

    // Use modulo indexing to implement the broadcasting rule:
    // - If length is 1, i % 1 == 0 so we repeat the single element.
    // - If length equals out_len, i % length == i for i < length, so we copy.
    for i in 0..out_len {
        a_out.push(a[i % m]);
        b_out.push(b[i % n]);
    }

    (a_out, b_out)
}